import"./chunk-VC46IEJQ.js";var l={en:"No sigil is described in the books; the family is identified by its name and its pyramid.",zh:"\u4E66\u4E2D\u672A\u63CF\u8FF0\u5176\u7EB9\u7AE0\uFF1B\u4EBA\u4EEC\u4EE5\u59D3\u6C0F\u548C\u5BB6\u65CF\u91D1\u5B57\u5854\u6765\u8FA8\u8BC6\u8FD9\u4E00\u5BB6\u65CF\u3002"},e=(a,n,o,s,r,i,t,h,d=[])=>({id:a,names:{en:n,zh:o},region:"slavers-bay",seat:s,tier:r,liege:null,sigil:l,colors:i,summary:t,refs:h,members:d}),m={group:"essos-east",houses:[e("loraq","House Loraq","\u6D1B\u62C9\u514B\u5BB6\u65CF","meereen","major",["#7a2e2a","#d9b46a"],{en:"One of the oldest and noblest families of Meereen, said to descend from ancient Ghiscari rulers. Its pyramid stands among the great ones of the city, and its head in the novels, Hizdahr, is a wealthy and conciliatory noble.",zh:"\u5F25\u6797\u6700\u53E4\u8001\u3001\u6700\u9AD8\u8D35\u7684\u5BB6\u65CF\u4E4B\u4E00\uFF0C\u636E\u8BF4\u662F\u53E4\u4EE3\u5409\u65AF\u7EDF\u6CBB\u8005\u7684\u540E\u88D4\u3002\u5BB6\u65CF\u91D1\u5B57\u5854\u4F4D\u5217\u57CE\u4E2D\u5927\u91D1\u5B57\u5854\u4E4B\u5217\uFF1B\u5C0F\u8BF4\u4E2D\u7684\u5BB6\u4E3B\u5E0C\u5179\u8FBE\u5C14\u662F\u4E00\u4F4D\u5BCC\u6709\u800C\u5584\u4E8E\u8C03\u548C\u7684\u8D35\u65CF\u3002"},["asos","adwd"],[{id:"hizdahr-zo-loraq",name:{en:"Hizdahr zo Loraq",zh:"\u5E0C\u5179\u8FBE\u5C14\xB7\u4F50\xB7\u6D1B\u62C9\u514B"},note:{en:"Meereenese noble of an ancient line; he petitions Daenerys to restore the fighting pits.",zh:"\u51FA\u8EAB\u53E4\u8001\u4E16\u5BB6\u7684\u5F25\u6797\u8D35\u65CF\uFF0C\u66FE\u5411\u4E39\u59AE\u8389\u4E1D\u8BF7\u613F\u91CD\u5F00\u89D2\u6597\u573A\u3002"},fate:{en:"Married Daenerys and was crowned King of Meereen to make peace with Yunkai (ADWD); he is suspected of links to the Sons of the Harpy and is imprisoned after her disappearance.",zh:"\u4E3A\u4E0E\u6E0A\u51EF\u8BAE\u548C\uFF0C\u4ED6\u5A36\u4E86\u4E39\u59AE\u8389\u4E1D\u5E76\u52A0\u5195\u4E3A\u5F25\u6797\u56FD\u738B\uFF08\u5377\u4E94\uFF09\uFF1B\u4ED6\u88AB\u6000\u7591\u4E0E\u9E70\u8EAB\u5973\u5996\u4E4B\u5B50\u6709\u6240\u52FE\u8FDE\uFF0C\u5728\u4E39\u59AE\u8389\u4E1D\u5931\u8E2A\u540E\u906D\u5230\u56DA\u7981\u3002"},spoiler:!1},{id:"marghaz-zo-loraq",name:{en:"Marghaz zo Loraq",zh:"\u9A6C\u683C\u54C8\u5179\xB7\u4F50\xB7\u6D1B\u62C9\u514B"},note:{en:"Hizdahr's cousin, given command of the Brazen Beasts in ADWD.",zh:"\u5E0C\u5179\u8FBE\u5C14\u7684\u5802\u4EB2\uFF0C\u5377\u4E94\u4E2D\u88AB\u4EFB\u547D\u7EDF\u9886\u94DC\u517D\u3002"},spoiler:!1}]),e("pahl","House Pahl","\u5E15\u5C14\u5BB6\u65CF","meereen","major",["#3f4a6b","#c9a24a"],{en:"A proud Meereenese family whose sons served in the city's defence. Its champion rode out to mock the besiegers when Meereen was attacked, and the family later had blood scores to settle with the city's new rulers.",zh:"\u9A84\u50B2\u7684\u5F25\u6797\u5BB6\u65CF\uFF0C\u5BB6\u4E2D\u5B50\u5F1F\u66FE\u53C2\u4E0E\u5B88\u57CE\u3002\u5F25\u6797\u906D\u56F4\u653B\u65F6\uFF0C\u5BB6\u65CF\u7684\u52C7\u58EB\u66FE\u9A91\u9A6C\u51FA\u57CE\u5632\u5F04\u56F4\u57CE\u8005\uFF1B\u6B64\u540E\u8BE5\u5BB6\u65CF\u4E0E\u57CE\u5E02\u7684\u65B0\u7EDF\u6CBB\u8005\u7ED3\u4E0B\u8840\u4EC7\u3002"},["asos","adwd"],[{id:"oznak-zo-pahl",name:{en:"Oznak zo Pahl",zh:"\u5965\u5179\u7EB3\u514B\xB7\u4F50\xB7\u5E15\u5C14"},note:{en:"Meereenese champion who rode out to challenge the besiegers at the gates.",zh:"\u5F25\u6797\u52C7\u58EB\uFF0C\u9A91\u9A6C\u51FA\u57CE\u5411\u57CE\u4E0B\u7684\u56F4\u57CE\u8005\u6311\u6218\u3002"},fate:{en:"Slain in single combat by Strong Belwas (ASOS).",zh:"\u5728\u5355\u6311\u4E2D\u88AB\u58EE\u6C49\u8D1D\u6C83\u65AF\u6240\u6740\uFF08\u5377\u4E09\uFF09\u3002"},spoiler:!1}]),e("galare","House Galare","\u52A0\u62C9\u5C14\u5BB6\u65CF","meereen","major",["#2f5d4a","#e8dcb5"],{en:"An old Meereenese family closely tied to the Temple of the Graces. Its most prominent member is the Green Grace, the high priestess who acts as a go-between for the city's nobles.",zh:"\u4E0E\u7F8E\u60E0\u795E\u5E99\u5173\u7CFB\u5BC6\u5207\u7684\u5F25\u6797\u53E4\u8001\u5BB6\u65CF\u3002\u5176\u6700\u8457\u540D\u7684\u6210\u5458\u662F\u7EFF\u8272\u5723\u5973\uFF0C\u5979\u8EAB\u4E3A\u5927\u796D\u53F8\uFF0C\u5E38\u5728\u57CE\u4E2D\u8D35\u65CF\u4E4B\u95F4\u65A1\u65CB\u3002"},["asos","adwd"],[{id:"galazza-galare",name:{en:"Galazza Galare",zh:"\u845B\u62C9\u672D\xB7\u52A0\u62C9\u5C14"},note:{en:"The Green Grace, high priestess of the Temple of the Graces and an adviser to Daenerys.",zh:"\u7EFF\u8272\u5723\u5973\uFF0C\u7F8E\u60E0\u795E\u5E99\u7684\u5927\u796D\u53F8\uFF0C\u4E39\u59AE\u8389\u4E1D\u7684\u987E\u95EE\u3002"},spoiler:!1},{id:"grazdan-zo-galare",name:{en:"Grazdan zo Galare",zh:"\u683C\u62C9\u5179\u4E39\xB7\u4F50\xB7\u52A0\u62C9\u5C14"},note:{en:"Meereenese noble of the family named in ADWD.",zh:"\u5377\u4E94\u4E2D\u63D0\u53CA\u7684\u8BE5\u5BB6\u65CF\u5F25\u6797\u8D35\u65CF\u3002"},spoiler:!1}]),e("merreq","House Merreq","\u6885\u745E\u514B\u5BB6\u65CF","meereen","minor",["#5a3b2a","#cfa66a"],{en:"One of the Meereenese great families named in ADWD, which gave children to Daenerys's court as hostages. The novels give no further detail about it.",zh:"\u5377\u4E94\u4E2D\u63D0\u53CA\u7684\u5F25\u6797\u540D\u95E8\u4E4B\u4E00\uFF0C\u66FE\u5C06\u5B50\u5973\u9001\u5165\u4E39\u59AE\u8389\u4E1D\u7684\u5BAB\u5EF7\u5145\u5F53\u4EBA\u8D28\u3002\u5C0F\u8BF4\u4E2D\u522B\u65E0\u66F4\u591A\u7EC6\u8282\u3002"},["adwd"]),e("ghazeen","House Ghazeen","\u52A0\u6D25\u5BB6\u65CF","meereen","minor",["#6b5a2a","#e0c070"],{en:"A Meereenese pyramid family named in ADWD among the nobles who sent hostages to the queen. Little else is said of it.",zh:"\u5377\u4E94\u4E2D\u63D0\u5230\u7684\u5F25\u6797\u91D1\u5B57\u5854\u5BB6\u65CF\uFF0C\u66FE\u5411\u5973\u738B\u9001\u4EA4\u4EBA\u8D28\u3002\u6B64\u5916\u7740\u58A8\u751A\u5C11\u3002"},["adwd"]),e("rhazdar","House Rhazdar","\u62C9\u5179\u8FBE\u5BB6\u65CF","meereen","minor",["#4a2f3f","#d4b080"],{en:"One of the old families of Meereen whose name appears in ADWD. The novels describe nothing more of it.",zh:"\u5377\u4E94\u4E2D\u51FA\u73B0\u8FC7\u540D\u5B57\u7684\u5F25\u6797\u53E4\u8001\u5BB6\u65CF\u4E4B\u4E00\u3002\u5C0F\u8BF4\u4E2D\u6CA1\u6709\u66F4\u591A\u63CF\u8FF0\u3002"},["adwd"]),e("zhak","House Zhak","\u672D\u514B\u5BB6\u65CF","meereen","minor",["#2f3f4a","#c8b48a"],{en:"A noble family of Meereen named in ADWD, among those whose children served as the queen's cupbearers and hostages.",zh:"\u5377\u4E94\u4E2D\u63D0\u5230\u7684\u5F25\u6797\u8D35\u65CF\u5BB6\u65CF\uFF0C\u5176\u5B50\u5973\u66FE\u4F5C\u4E3A\u5973\u738B\u7684\u4F8D\u9152\u7AE5\u548C\u4EBA\u8D28\u3002"},["adwd"]),e("hazkar","House Hazkar","\u54C8\u5179\u5361\u5BB6\u65CF","meereen","minor",["#3d4a2a","#d8c27a"],{en:"A Meereenese noble house mentioned in ADWD among the city's pyramid families. Nothing else is recorded about it.",zh:"\u5377\u4E94\u4E2D\u63D0\u5230\u7684\u5F25\u6797\u91D1\u5B57\u5854\u5BB6\u65CF\u4E4B\u4E00\u3002\u522B\u65E0\u66F4\u591A\u8BB0\u8F7D\u3002"},["adwd"]),e("uhlez","House Uhlez","\u4E4C\u52D2\u5179\u5BB6\u65CF","meereen","minor",["#4a3a5a","#d6bf8a"],{en:"One of the pyramid families of Meereen named in ADWD. The novels say little more than its name and its pyramid.",zh:"\u5377\u4E94\u4E2D\u63D0\u5230\u7684\u5F25\u6797\u91D1\u5B57\u5854\u5BB6\u65CF\u4E4B\u4E00\u3002\u5C0F\u8BF4\u4E2D\u9664\u540D\u5B57\u4E0E\u91D1\u5B57\u5854\u5916\u51E0\u4E4E\u6CA1\u6709\u7740\u58A8\u3002"},["adwd"]),e("kandaq","House Kandaq","\u574E\u8FBE\u514B\u5BB6\u65CF","meereen","minor",["#5a2a2a","#b8b0a0"],{en:"A lesser Meereenese family, known through its member Skahaz, who shaved his head to show he had broken with the old ways and served the new queen.",zh:"\u5F25\u6797\u7684\u6B21\u7B49\u5BB6\u65CF\uFF0C\u56E0\u5176\u6210\u5458\u65AF\u5361\u54C8\u5179\u800C\u4E3A\u4EBA\u6240\u77E5\uFF1B\u4ED6\u5243\u5149\u5934\u53D1\u4EE5\u793A\u4E0E\u65E7\u4FD7\u51B3\u88C2\uFF0C\u8F6C\u800C\u6548\u5FE0\u65B0\u5973\u738B\u3002"},["asos","adwd"],[{id:"skahaz-mo-kandaq",name:{en:"Skahaz mo Kandaq",zh:"\u65AF\u5361\u54C8\u5179\xB7\u83AB\xB7\u574E\u8FBE\u514B"},note:{en:"The Shavepate, commander of the Brazen Beasts and Daenerys's most hawkish Meereenese adviser.",zh:"\u201C\u5243\u5934\u8005\u201D\uFF0C\u94DC\u517D\u7684\u6307\u6325\u5B98\uFF0C\u4E39\u59AE\u8389\u4E1D\u7684\u5F25\u6797\u987E\u95EE\u4E2D\u6700\u5F3A\u786C\u7684\u4E00\u4F4D\u3002"},spoiler:!1}]),e("reznak","Reznak family","\u96F7\u5179\u7EB3\u514B\u5BB6\u65CF","meereen","minor",["#4a4a2a","#e6d39a"],{en:"The family of Reznak mo Reznak, the perfumed seneschal who served Daenerys in Meereen. The books treat him as a man of the city rather than of a great house, so this entry is kept minimal.",zh:"\u96F7\u5179\u7EB3\u514B\xB7\u83AB\xB7\u96F7\u5179\u7EB3\u514B\u7684\u5BB6\u65CF\uFF1B\u8FD9\u4F4D\u6EE1\u8EAB\u9999\u6C14\u7684\u603B\u7BA1\u66FE\u5728\u5F25\u6797\u4E3A\u4E39\u59AE\u8389\u4E1D\u6548\u529B\u3002\u4E66\u4E2D\u5C06\u4ED6\u89C6\u4E3A\u57CE\u4E2D\u4EBA\u58EB\u800C\u975E\u540D\u95E8\u51FA\u8EAB\uFF0C\u6545\u6B64\u6761\u76EE\u4ECE\u7B80\u3002"},["asos","adwd"],[{id:"reznak-mo-reznak",name:{en:"Reznak mo Reznak",zh:"\u96F7\u5179\u7EB3\u514B\xB7\u83AB\xB7\u96F7\u5179\u7EB3\u514B"},note:{en:"Seneschal of Meereen under Daenerys, obsequious and heavily perfumed.",zh:"\u4E39\u59AE\u8389\u4E1D\u6CBB\u4E0B\u7684\u5F25\u6797\u603B\u7BA1\uFF0C\u8C04\u5A9A\u9022\u8FCE\uFF0C\u6D51\u8EAB\u9999\u6C14\u3002"},spoiler:!1}]),e("qaggaz","House Qaggaz","\u5361\u52A0\u5179\u5BB6\u65CF","yunkai","minor",["#8a6d1f","#f1df9a"],{en:"A family of the Wise Masters of Yunkai. Its member Yezzan is one of the richest slavers of the city and owns a troupe of grotesques and performers.",zh:"\u6E0A\u51EF\u667A\u8005\u7684\u5BB6\u65CF\u4E4B\u4E00\u3002\u5176\u6210\u5458\u8036\u8D5E\u662F\u57CE\u4E2D\u6700\u5BCC\u6709\u7684\u5974\u96B6\u4E3B\u4E4B\u4E00\uFF0C\u84C4\u517B\u7740\u4E00\u73ED\u7578\u4EBA\u4E0E\u827A\u4EBA\u3002"},["adwd"],[{id:"yezzan-zo-qaggaz",name:{en:"Yezzan zo Qaggaz",zh:"\u8036\u8D5E\xB7\u4F50\xB7\u5361\u52A0\u5179"},note:{en:"Grossly fat Yunkish Wise Master at the siege of Meereen, a collector of slaves with deformities and talents.",zh:"\u53C2\u52A0\u5F25\u6797\u56F4\u653B\u7684\u6E0A\u51EF\u667A\u8005\uFF0C\u6781\u5EA6\u80A5\u80D6\uFF0C\u4E13\u95E8\u6536\u96C6\u7578\u5F62\u6216\u8EAB\u6000\u6280\u827A\u7684\u5974\u96B6\u3002"},fate:{en:"Fell sick with the bloody flux in the camp outside Meereen (ADWD).",zh:"\u5728\u5F25\u6797\u57CE\u5916\u8425\u5730\u67D3\u4E0A\u8840\u75E2\uFF08\u5377\u4E94\uFF09\u3002"},spoiler:!1}]),e("eraz","House Eraz","\u57C3\u62C9\u5179\u5BB6\u65CF","yunkai","minor",["#9a7a2a","#f4e4b0"],{en:"A Yunkish family of the Wise Masters, known through the envoy who came out to treat with the dragon queen before the walls of Yunkai.",zh:"\u6E0A\u51EF\u667A\u8005\u5BB6\u65CF\u4E4B\u4E00\uFF0C\u56E0\u5176\u4F7F\u8005\u5728\u6E0A\u51EF\u57CE\u4E0B\u4E0E\u9F99\u5973\u738B\u8C08\u5224\u800C\u4E3A\u4EBA\u6240\u77E5\u3002"},["asos"],[{id:"grazdan-mo-eraz",name:{en:"Grazdan mo Eraz",zh:"\u683C\u62C9\u5179\u4E39\xB7\u83AB\xB7\u57C3\u62C9\u5179"},note:{en:"Yunkish envoy sent to negotiate with Daenerys outside the city.",zh:"\u6E0A\u51EF\u6D3E\u5F80\u57CE\u5916\u4E0E\u4E39\u59AE\u8389\u4E1D\u8C08\u5224\u7684\u4F7F\u8005\u3002"},spoiler:!1}]),e("nakloz","House Nakloz","\u7EB3\u514B\u7F57\u5179\u5BB6\u65CF","astapor","minor",["#8a2a1f","#e8c49a"],{en:"A family of the Good Masters of Astapor, slave-traders who dealt in the Unsullied.",zh:"\u963F\u65AF\u5854\u6CE2\u5584\u4E3B\u5BB6\u65CF\u4E4B\u4E00\uFF0C\u4EE5\u4E70\u5356\u65E0\u57A2\u8005\u4E3A\u4E1A\u7684\u5974\u96B6\u5546\u3002"},["asos"],[{id:"kraznys-mo-nakloz",name:{en:"Kraznys mo Nakloz",zh:"\u514B\u62C9\u5179\u5C3C\xB7\u83AB\xB7\u7EB3\u514B\u7F57\u5179"},note:{en:"Arrogant Good Master who showed the Unsullied to Daenerys, speaking only Ghiscari through an interpreter.",zh:"\u50B2\u6162\u7684\u5584\u4E3B\uFF0C\u66FE\u5411\u4E39\u59AE\u8389\u4E1D\u5C55\u793A\u65E0\u57A2\u8005\uFF0C\u53EA\u80AF\u901A\u8FC7\u8BD1\u8005\u8BF4\u5409\u65AF\u5361\u5229\u8BED\u3002"},fate:{en:"Burned by Drogon when Daenerys turned the Unsullied on their masters (ASOS).",zh:"\u4E39\u59AE\u8389\u4E1D\u4EE4\u65E0\u57A2\u8005\u5012\u6208\u4E4B\u65F6\uFF0C\u88AB\u5353\u803F\u70E7\u6B7B\uFF08\u5377\u4E09\uFF09\u3002"},spoiler:!1}]),{id:"xho",names:{en:"House Xho",zh:"\u68AD\u5BB6\u65CF"},region:"summer-isles",seat:"red-flower-vale",tier:"minor",liege:null,sigil:{en:"No sigil is described; the prince wears the bright feathered cloaks of the Summer Isles.",zh:"\u4E66\u4E2D\u672A\u63CF\u8FF0\u7EB9\u7AE0\uFF1B\u738B\u5B50\u8EAB\u62AB\u76DB\u590F\u7FA4\u5C9B\u7279\u6709\u7684\u9C9C\u8273\u7FBD\u6BDB\u6597\u7BF7\u3002"},colors:["#b8322a","#f2c94c"],summary:{en:"The family of the exiled princes of the Red Flower Vale in the Summer Isles. Its prince lives at the Iron Throne's court, petitioning in vain for men to win back his home.",zh:"\u76DB\u590F\u7FA4\u5C9B\u7EA2\u82B1\u8C37\u6D41\u4EA1\u738B\u65CF\u3002\u5176\u738B\u5B50\u5BC4\u5C45\u94C1\u738B\u5EA7\u5BAB\u5EF7\uFF0C\u5F92\u52B3\u5730\u8BF7\u6C42\u501F\u5175\u6536\u590D\u6545\u571F\u3002"},refs:["agot","acok"],members:[{id:"jalabhar-xho",name:{en:"Jalabhar Xho",zh:"\u8D3E\u62C9\u5DF4\xB7\u68AD"},note:{en:"Exiled Prince of the Red Flower Vale, a courtier in King's Landing.",zh:"\u6D41\u4EA1\u7684\u7EA2\u82B1\u8C37\u738B\u5B50\uFF0C\u541B\u4E34\u5BAB\u5EF7\u4E2D\u7684\u4E00\u5458\u3002"},spoiler:!1}]}]};export{m as default};
